#include <stdexcept>

class Position {
public:
    int qty() const { return qty_; }
    double avg_price() const { return avg_; }
    double realised() const { return realised_; }

    void buy(int qty, double px) {
        if (qty <= 0 || px <= 0) throw std::invalid_argument("bad buy");
        avg_ = (qty_ * avg_ + qty * px) / (qty_ + qty);
        qty_ += qty;
    }

    double sell(int qty, double px) {
        if (qty <= 0 || px <= 0 || qty > qty_) throw std::invalid_argument("bad sell");
        double pnl = qty * (px - avg_);
        realised_ += pnl;
        qty_ -= qty;
        if (qty_ == 0) avg_ = 0.0;
        return pnl;
    }

private:
    int qty_ = 0;
    double avg_ = 0.0;
    double realised_ = 0.0;
};

