#include <string>

template <int Places>
class Fixed {
public:
    static Fixed from_units(long long u) {
        Fixed f;
        f.units_ = u;
        return f;
    }
    long long units() const { return units_; }
    std::string str() const {
        long long scale = 1;
        for (int i = 0; i < Places; ++i) scale *= 10;
        long long u = units_ < 0 ? -units_ : units_;
        std::string out = (units_ < 0 ? "-" : "") + std::to_string(u / scale);
        if (Places > 0) {
            std::string frac = std::to_string(u % scale);
            while (static_cast<int>(frac.size()) < Places) frac = "0" + frac;
            out += "." + frac;
        }
        return out;
    }
private:
    long long units_ = 0;
};

template <int Places>
Fixed<Places> operator+(Fixed<Places> a, Fixed<Places> b) {
    return Fixed<Places>::from_units(a.units() + b.units());
}

